"""Compare the numbers printed in the paper with the numbers the code produces.

    python check_paper.py            # reads results/summary.json, results/channel.json,
                                     # results/derived.json (committed, or regenerated by run_all)

Each row shows the value as printed in the paper, the value recomputed from the
result files with the same rounding, and whether they agree.  Exit code 0 when
every row agrees.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

HERE = Path(__file__).parent
RES = HERE / "results"
S = json.loads((RES / "summary.json").read_text())
CH = json.loads((RES / "channel.json").read_text())
D = json.loads((RES / "derived.json").read_text())


def kn(x):
    return f"{x['k']}/{x['n']}"


def ci(x):
    return f"[{x['ci'][0]:.2f}, {x['ci'][1]:.2f}]"


def folds(x):
    return f"{x['folds'][0]:.2f}--{x['folds'][1]:.2f}"


def plc(x):
    p = x["placebo"]
    return "0" if p == 0 else f"{p:.2f}"


def lat(x):
    return f"{x['latency_median_s']:.0f}"


def day(x):
    return f"{x['per_day']:.0f} [{x['ci'][0]:.0f}, {x['ci'][1]:.0f}]"


C, L, A, B = S["classes"], S["long"], S["adaptive"], S["benign"]
fc = S["floor_check"]
short_pred = 1 - fc["predicted_miss"] / fc["episodes"]

# (where in the paper, what the paper prints, what the code gives)
ROWS = [("Sec. V channel", "D = 0.466 / 0.379", f"D = {CH['A']['D']:.3f} / {CH['B']['D']:.3f}"),
        ("Sec. V channel", "p = 0.002 / 0.002", f"p = {CH['A']['p']:.3f} / {CH['B']['p']:.3f}"),
        ("Sec. V channel", "eps 0.54--0.85, median 0.69",
         f"eps {min(CH['A']['eps'][0], CH['B']['eps'][0]):.2f}--{max(CH['A']['eps'][2], CH['B']['eps'][2]):.2f}, "
         f"median {D['pooled']['eps']:.2f}"),
        ("Sec. V channel", "1-gamma 0.79, s 0.24", f"1-gamma {D['pooled']['omg']:.2f}, s {D['pooled']['s']:.2f}"),
        ("Sec. V channel", "about 102 uplinks; f < 0.24; 0.10 nats",
         f"about {D['n_certify_f1']:.0f} uplinks; f < {D['fmin_100_b']:.2f}; {D['I_f08']:.2f} nats"),
        ("Sec. V suppression", "SUP needs 52--146 uplinks (median 90)",
         f"SUP needs {fc['required_range'][0]:.0f}--{fc['required_range'][1]:.0f} uplinks (median {fc['required_median']:.0f})"),
        ("Sec. V suppression", "35 of 39 predicted misses missed",
         f"{fc['missed_of_predicted']} of {fc['predicted_miss']} predicted misses missed"),
        ("Sec. V suppression", "ln u_d >= 9.9; episode 2.7--27.9 nats; 1.11x delay",
         f"ln u_d >= {D['ln_ud_min']:.1f}; episode {D['episode_nats'][0]:.1f}--{D['episode_nats'][1]:.1f} nats; "
         f"{D['long_latency_over_pred_median']:.2f}x delay")]

T2 = [("Hide f=0.8, long", L["lh08"], "55/60 [0.82, 0.97] | 0.50--1.00 | 0 | 306 | 1.00", f"{L['lh08']['predicted_detect']:.2f}"),
      ("Hide f=1, long", L["lh10"], "60/60 [0.94, 1.00] | 1.00--1.00 | 0 | 194 | 1.00", f"{L['lh10']['predicted_detect']:.2f}"),
      ("Hide f=0.8, short", C["hide"], "16/60 [0.16, 0.40] | 0.00--0.50 | 0 | 155 | 0.35", f"{short_pred:.2f}"),
      ("Delay 30 s", C["delay"], "26/60 [0.31, 0.57] | 0.00--1.00 | 0 | 190 | --", "--"),
      ("Change +60 B", C["change"], "22/60 [0.25, 0.50] | 0.00--0.50 | 0.03 | 72 | --", "--"),
      ("Leak, new host", C["leak"], "48/60 [0.68, 0.89] | 0.00--1.00 | 0.17 | 59 | --", "--"),
      ("Forge, host-timed ACK", C["forge"], "59/60 [0.91, 1.00] | 0.90--1.00 | 0 | 21 | --", "--"),
      ("Forge, firmware-exact ACK", C["forgeX"], "14/60 [0.13, 0.36] | 0.00--0.50 | 0 | 133 | --", "--"),
      ("Invent", C["invent"], "6/60 [0.04, 0.21] | 0.00--0.60 | 0.07 | 12 | --", "--"),
      ("Swap", C["swap"], "1/60 [0.00, 0.09] | 0.00--0.10 | 0.02 | 215 | --", "--")]
for name, x, paper, pred in T2:
    ROWS.append((f"Table II  {name}", paper, f"{kn(x)} {ci(x)} | {folds(x)} | {plc(x)} | {lat(x)} | {pred}"))

T3 = [("B=1", B["1.0"], "234 [86, 510] | 117 [24, 342] | 273 [110, 563]"),
      ("B=100", B["100.0"], "429 [214, 768] | 273 [110, 563] | 468 [242, 818]"),
      ("B=1000", B["1000.0"], "1327 [919, 1855] | 1015 [663, 1487] | 1210 [822, 1718]")]
for name, x, paper in T3:
    ROWS.append((f"Table III {name}", paper, " | ".join(day(x[c]["core"]) for c in ("bern", "disp", "markov"))))
lb = S["long_benign"]
ROWS.append(("Table III B=1, short commissioning", "410 [254, 627] | 371 [223, 579] | 449 [285, 674]",
             " | ".join(day(lb[c]) for c in ("bern", "disp", "markov"))))


def ks(*keys):
    return " / ".join(str(A[k]["k"]) for k in keys)


ROWS += [("Table IV A1", "16/60, plc 0, 206 s", f"{kn(A['a1'])}, plc {plc(A['a1'])}, {lat(A['a1'])} s"),
         ("Table IV A2a/b/c", "53 / 7 / 1 of 60", f"{ks('a2a', 'a2b', 'a2c')} of 60"),
         ("Table IV A3 1/60, 1/20, 1/5 s", "5 / 6 / 30 of 30, plc 0.17", f"{ks('a3_60', 'a3_20', 'a3_5')} of 30, plc {plc(A['a3_5'])}"),
         ("Table IV A4 32-bit", "26 / 30 / 12 of 60", f"{ks('a4_32_no', 'a4_32_sw', 'a4_32_ex')} of 60"),
         ("Table IV A4 8-bit", "20 / 22 / 7 of 60", f"{ks('a4_8_no', 'a4_8_sw', 'a4_8_ex')} of 60"),
         ("Table IV A5", "16/60", kn(A["a5"])),
         ("Table IV A7 / A7'", "0 / 0 of 60; 14% / 12% hidden",
          f"{ks('a7', 'a7p')} of 60; {100 * A['a7']['hidden'] / A['a7']['candidates']:.0f}% / "
          f"{100 * A['a7p']['hidden'] / A['a7p']['candidates']:.0f}% hidden"),
         ("Table IV A8 +50% / +100%", "31 / 48 of 60, plc 0.17", f"{ks('a8_50', 'a8_100')} of 60, plc {plc(A['a8_50'])}"),
         ("Table IV A9 LIVE / none", "60 / 0 of 60, 29 s", f"{ks('a9', 'a9_nolive')} of 60, {lat(A['a9'])} s"),
         ("Table IV A10", "10/60", kn(A["a10"])),
         ("Sec. V counters", "11,385 frames, 0 collisions, 0.30% 8-bit backsteps",
          f"{S['counters']['fc32_frames']:,} frames, {S['counters']['fc32_events']} collisions, "
          f"{100 * S['counters']['seq8_rate']:.2f}% 8-bit backsteps")]


def main():
    w0 = max(len(r[0]) for r in ROWS)
    bad = 0
    print(f"{'where':{w0}s}  {'match':5s}  paper  ->  code")
    for where, paper, code in ROWS:
        ok = paper == code
        bad += not ok
        print(f"{where:{w0}s}  {'yes' if ok else 'NO':5s}  {paper}" + ("" if ok else f"  ->  {code}"))
    print()
    print(f"{len(ROWS) - bad}/{len(ROWS)} rows agree with the paper")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
